mapper.select:
/* 삭제되지 않은 반려동물 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM PET
        WHERE PET_SN = #{petSn}
          AND DEL_YN = 'N'
       )

/* 회원의 반려동물 양육 역할 코드 조회 */
SELECT R.BRUP_ROLE_CD
  FROM BRUP_REL R
  JOIN PET P
    ON P.PET_SN = R.PET_SN
 WHERE R.PET_SN = #{petSn}
   AND R.MBR_SN = #{mbrSn}
   AND R.USE_YN = 'Y'
   AND P.DEL_YN = 'N'

/* 회원이 양육하는 반려동물 번호 목록 조회 (연동 해제·삭제된 반려동물 제외) */
SELECT R.PET_SN
  FROM BRUP_REL R
  JOIN PET P
    ON P.PET_SN = R.PET_SN
 WHERE R.MBR_SN = #{mbrSn}
   AND R.BRUP_ROLE_CD IN

       #{brupRoleCd}

   AND R.USE_YN = 'Y'
   AND P.DEL_YN = 'N'

   AND R.PET_SN IN

       #{petSn}


 ORDER BY R.PET_SN
